import sys

def main():
    n = int(sys.stdin.readline())
    s = sys.stdin.readline().strip()

    count = 0
    for l in range(n):
        num = 0
        for r in range(l, n):
            num = num * 10 + int(s[r])
            if num % 2 == 0:
                count += 1
    print(count)

main()
